import java.util.*;

public class CYKEngine {

    /** Returns true iff the input string can be generated by the supplied CNF grammar. */
    public static boolean parse(String input, Types.Grammar grammar) {
        Objects.requireNonNull(input);
        Objects.requireNonNull(grammar);

        int n = input.length();
        if (n == 0) {
            // CNF does not allow ε‑productions (except possibly for the start symbol,
            // which we deliberately do not support here). Hence empty string is rejected.
            return false;
        }

        // table[i][l] = set of non‑terminals that derive substring starting at i with length l
        @SuppressWarnings("unchecked")
        Set<String>[][] table = new HashSet[n][n + 1];
        for (int i = 0; i < n; i++) {
            for (int l = 1; l <= n - i; l++) {
                table[i][l] = new HashSet<>();
            }
        }

        // Base case: substrings of length 1 (terminals)
        for (int i = 0; i < n; i++) {
            String a = String.valueOf(input.charAt(i));
            for (Types.Rule r : grammar.rules) {
                if (r.isTerminal() && r.right.get(0).equals(a)) {
                    table[i][1].add(r.left);
                }
            }
        }

        // Fill DP table for lengths >= 2
        for (int l = 2; l <= n; l++) {               // current substring length
            for (int i = 0; i <= n - l; i++) {        // start position
                for (int split = 1; split < l; split++) { // split point
                    Set<String> leftSet = table[i][split];
                    Set<String> rightSet = table[i + split][l - split];
                    if (leftSet.isEmpty() || rightSet.isEmpty()) {
                        continue;
                    }
                    for (Types.Rule r : grammar.rules) {
                        if (!r.isTerminal() && r.right.size() == 2) {
                            String B = r.right.get(0);
                            String C = r.right.get(1);
                            if (leftSet.contains(B) && rightSet.contains(C)) {
                                table[i][l].add(r.left);
                            }
                        }
                    }
                }
            }
        }

        // Accept if start symbol derives the whole string
        return table[0][n].contains(grammar.startSymbol);
    }
}
